class SafeDeleteObjectPanel(bpy.types.Panel):
    bl_label = "Safe Delete Object"
    bl_idname = "PT_SafeDeleteObject"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Tools'

    def draw(self, context):
        layout = self.layout
        layout.operator("object.safe_delete", text="Safe Delete Object")

class SafeDeleteOperator(bpy.types.Operator):
    bl_idname = "object.safe_delete"
    bl_label = "Safe Delete"

    def execute(self, context):
        obj = context.object
        if obj is not None:
            for ob in bpy.data.objects:
                if ob.parent == obj:
                    self.report({'WARNING'}, "Cannot delete object as it is a parent!")
                    return {'CANCELLED'}
            bpy.ops.object.delete()
        else:
            self.report({'WARNING'}, "No object selected!")
        return {'FINISHED'}

def register():
    bpy.utils.register_class(SafeDeleteObjectPanel)
    bpy.utils.register_class(SafeDeleteOperator)

def unregister():
    bpy.utils.unregister_class(SafeDeleteObjectPanel)
    bpy.utils.unregister_class(SafeDeleteOperator)

