class MassCalculatorPanel(bpy.types.Panel):
    bl_label = "Mass Calculator"
    bl_idname = "PT_MassCalculator"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Tools'

    def draw(self, context):
        layout = self.layout
        layout.prop(context.scene, "density")
        layout.operator("object.calculate_mass", text="Calculate Mass")
        layout.label(text=f"Mass: {context.scene.mass:.2f} kg")

class CalculateMassOperator(bpy.types.Operator):
    bl_idname = "object.calculate_mass"
    bl_label = "Calculate Mass"

    def execute(self, context):
        obj = context.active_object
        if obj.type != 'MESH':
            self.report({'ERROR'}, "Selected object is not a mesh")
            return {'CANCELLED'}
        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
        volume = sum(f.calc_area() for f in obj.data.polygons)
        if volume == 0:
            self.report({'ERROR'}, "Object has zero volume")
            return {'CANCELLED'}
        context.scene.mass = volume * context.scene.density
        return {'FINISHED'}

def register():
    bpy.utils.register_class(MassCalculatorPanel)
    bpy.utils.register_class(CalculateMassOperator)
    bpy.types.Scene.density = bpy.props.FloatProperty(name="Density", default=1.0)
    bpy.types.Scene.mass = bpy.props.FloatProperty(name="Mass", default=0.0)

def unregister():
    bpy.utils.unregister_class(MassCalculatorPanel)
    bpy.utils.unregister_class(CalculateMassOperator)
    del bpy.types.Scene.density
    del bpy.types.Scene.mass

if __name__ == "__main__":
    register()

