class ShaderSwitcherPanel(bpy.types.Panel):
    bl_label = "Dynamic Shader Switcher"
    bl_idname = "PT_ShaderSwitcher"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Shading'

    def draw(self, context):
        layout = self.layout
        layout.operator("object.switch_to_glossy", text="Switch to Glossy Shader")
        layout.operator("object.switch_to_diffuse", text="Switch to Diffuse Shader")

class SwitchToGlossyOperator(bpy.types.Operator):
    bl_idname = "object.switch_to_glossy"
    bl_label = "Switch to Glossy Shader"

    def execute(self, context):
        obj = context.active_object
        if not obj.material_slots:
            self.report({'ERROR'}, "Object has no material slots")
            return {'CANCELLED'}
        mat = obj.material_slots[0].material
        if not mat.node_tree:
            mat.use_nodes = True
        nodes = mat.node_tree.nodes
        for node in nodes:
            nodes.remove(node)
        shader = nodes.new(type='ShaderNodeBsdfGlossy')
        output = nodes.new(type='ShaderNodeOutputMaterial')
        mat.node_tree.links.new(shader.outputs[0], output.inputs[0])
        return {'FINISHED'}

class SwitchToDiffuseOperator(bpy.types.Operator):
    bl_idname = "object.switch_to_diffuse"
    bl_label = "Switch to Diffuse Shader"

    def execute(self, context):
        obj = context.active_object
        if not obj.material_slots:
            self.report({'ERROR'}, "Object has no material slots")
            return {'CANCELLED'}
        mat = obj.material_slots[0].material
        if not mat.node_tree:
            mat.use_nodes = True
        nodes = mat.node_tree.nodes
        for node in nodes:
            nodes.remove(node)
        shader = nodes.new(type='ShaderNodeBsdfDiffuse')
        output = nodes.new(type='ShaderNodeOutputMaterial')
        mat.node_tree.links.new(shader.outputs[0], output.inputs[0])
        return {'FINISHED'}

def register():
    bpy.utils.register_class(ShaderSwitcherPanel)
    bpy.utils.register_class(SwitchToGlossyOperator)
    bpy.utils.register_class(SwitchToDiffuseOperator)

def unregister():
    bpy.utils.unregister_class(ShaderSwitcherPanel)
    bpy.utils.unregister_class(SwitchToGlossyOperator)
    bpy.utils.unregister_class(SwitchToDiffuseOperator)

if __name__ == "__main__":
    register()
